import { useRef, useState } from "react";
import "./../styles/player.css";

export default function Player() {
  const audioRef = useRef(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [volume, setVolume] = useState(0.8);

  function togglePlay() {
    const audio = audioRef.current;
    if (!audio || isLoading) return;

    if (isPlaying) {
      audio.pause();
      setIsPlaying(false);
      return;
    }

    setIsLoading(true);
    const playPromise = audio.play();

    if (playPromise && typeof playPromise.then === "function") {
      playPromise
        .then(() => {
          setIsPlaying(true);
          setIsLoading(false);
        })
        .catch(() => {
          // Reprodução interrompida ou bloqueada pelo navegador —
          // simplesmente volta ao estado pausado, sem quebrar a UI.
          setIsPlaying(false);
          setIsLoading(false);
        });
    } else {
      setIsPlaying(true);
      setIsLoading(false);
    }
  }

  function handleVolumeChange(e) {
    const value = Number(e.target.value);
    setVolume(value);
    if (audioRef.current) {
      audioRef.current.volume = value;
    }
  }

  return (
    <div className="player-card">
      <div className="player-top">
        <span className="player-onair">
          <span className="player-onair-dot" />
          NO AR
        </span>
        <h2>OUÇA AO VIVO</h2>
      </div>

      <div className="player-main">
        <button
          type="button"
          className={`player-playbtn ${isPlaying ? "is-playing" : ""}`}
          onClick={togglePlay}
          disabled={isLoading}
          aria-label={isPlaying ? "Pausar transmissão" : "Tocar transmissão"}
        >
          {isLoading ? (
            <svg
              viewBox="0 0 24 24"
              width="24"
              height="24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.5"
              className="player-spinner"
            >
              <circle cx="12" cy="12" r="9" strokeOpacity="0.25" />
              <path d="M21 12a9 9 0 0 0-9-9" strokeLinecap="round" />
            </svg>
          ) : isPlaying ? (
            <svg viewBox="0 0 24 24" width="26" height="26" fill="currentColor">
              <rect x="5" y="4" width="5" height="16" rx="1.5" />
              <rect x="14" y="4" width="5" height="16" rx="1.5" />
            </svg>
          ) : (
            <svg viewBox="0 0 24 24" width="26" height="26" fill="currentColor">
              <path d="M6 4.5v15l13-7.5z" />
            </svg>
          )}
        </button>

        <div className="player-info">
          <span className="player-label">Tocando agora</span>
          <p className="player-track">Dua Lipa</p>

          <div className={`player-eq ${isPlaying ? "is-playing" : ""}`}>
            <span></span>
            <span></span>
            <span></span>
            <span></span>
            <span></span>
          </div>
        </div>
      </div>

      <div className="player-volume">
        <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
          <path d="M5 9v6h4l5 5V4L9 9H5z" />
        </svg>
        <input
          type="range"
          min="0"
          max="1"
          step="0.01"
          value={volume}
          onChange={handleVolumeChange}
          aria-label="Volume"
        />
      </div>

      <audio
        ref={audioRef}
        onPause={() => setIsPlaying(false)}
        onError={() => {
          setIsPlaying(false);
          setIsLoading(false);
        }}
      >
        <source
          src="https://stream.zeno.fm/exemplo"
          type="audio/mpeg"
        />
      </audio>

      <button className="player-request">Pedir Música</button>
    </div>
  );
}
